def change(n,place,c,h,final,evidence,crop,kind,error,ac=False,ah=True,confidence='high',consequential=False,marked=False,typ='reading'):
    assert not c or c in C, (n,'C',c)
    assert h is None or not h or h in H, (n,'H',h)
    q=mc[crop]
    changes.append(dict(id=f'C{n:02}',place=place,C=c,H=h,final=final,evidence=evidence,crop=q['crop'],box=q['box'],confidence=confidence,kind=kind,error_kind=error,against_C=ac,against_H=ah,consequential=consequential,marked_in_H=marked,change_type=typ))
